import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Pressable, RefreshControl, ScrollView, Text, useWindowDimensions, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { router, useFocusEffect } from 'expo-router';
import { Avatar, EmptyState, ErrorText, ListView, Page, PageHeader, Toolbar, styles } from '../../../components/ui';
import { DirectThread } from '../../../components/direct-thread';
import { SocratesThread } from '../../../components/socrates-thread';
import { promptWebMessageAlerts } from '../../../components/dm-alert';
import { colors, fonts, fs, radius, viewportWidth } from '../../../lib/theme';
import { SOCRATES, canAskSocrates } from '../../../lib/config';
import { includeSocrates, SOCRATES_CONTACT_ID } from '../../../lib/chat-presence';
import { explainChatError, getProfiles, listBlocked, listDms, listMyGroupChats, openDm, type DmThread } from '../../../lib/api';
import { explainEventChatError, groupChatSubtitle, type GroupChatSummary } from '../../../lib/event-chats';
import { usePresence } from '../../../lib/presence';
import { setActivePushRoom } from '../../../lib/push';
import { useSession } from '../../../lib/session';
import { handle, primaryName } from '../../../lib/names';
import type { Profile } from '../../../lib/types';

const SPLIT_AT = 960;
const loadErr = (e: any) => explainChatError(String(e?.message ?? e), String(e?.message ?? 'Couldn’t load.'));

type OpenThread = { kind: 'socrates' } | { kind: 'dm'; roomId: string } | { kind: 'group'; roomId: string };

function PresenceLabel({ online, blocked, opening }: { online?: boolean; blocked?: boolean; opening?: boolean }) {
  const label = opening ? 'Opening…' : blocked ? 'Blocked' : online ? 'Online' : 'Offline';
  const color = opening ? colors.muted : blocked ? colors.danger : online ? colors.online : colors.faint;
  return <Text style={{ fontFamily: opening || !online ? fonts.sans : fonts.sansMedium, fontSize: fs(12), color, minWidth: 64, textAlign: 'right' }}>{label}</Text>;
}

function ConversationRow({ name, subtitle, online, path, userId, onPress, label, active, trailing }: {
  name: string; subtitle?: string | null; online?: boolean; path?: string | null; userId?: string | null;
  onPress: () => void; label: string; active?: boolean; trailing?: React.ReactNode;
}) {
  return (
    <Pressable onPress={onPress} accessibilityRole="button" accessibilityLabel={label} accessibilityState={{ selected: !!active }}>
      {({ pressed, hovered }: any) => (
        <View style={{
          flexDirection: 'row', alignItems: 'center', gap: 12,
          paddingHorizontal: 14, paddingVertical: 12,
          borderBottomWidth: 1, borderBottomColor: colors.line,
          backgroundColor: active ? colors.navySoft : pressed || hovered ? colors.rowHover : '#fff',
        }}>
          <Avatar name={name} path={path} userId={userId} size={42} online={online} />
          <View style={{ flex: 1, minWidth: 0 }}>
            <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(15), color: colors.ink }} numberOfLines={1}>{name}</Text>
            {subtitle ? <Text style={{ fontFamily: fonts.sans, fontSize: fs(13), color: colors.muted, marginTop: 2 }} numberOfLines={1}>{subtitle}</Text> : null}
          </View>
          {trailing}
        </View>
      )}
    </Pressable>
  );
}

function ToolRow({ title, subtitle, onPress, label }: { title: string; subtitle: string; onPress: () => void; label: string }) {
  return (
    <Pressable onPress={onPress} accessibilityRole="button" accessibilityLabel={label}>
      {({ pressed, hovered }: any) => (
        <View style={{
          flexDirection: 'row', alignItems: 'center', gap: 12,
          paddingHorizontal: 14, paddingVertical: 12,
          backgroundColor: pressed || hovered ? colors.rowHover : colors.card,
          borderWidth: 1, borderColor: colors.line, borderRadius: radius,
        }}>
          <View style={styles.headerIcon}><Ionicons name="people" size={18} color="#fff" /></View>
          <View style={{ flex: 1, minWidth: 0 }}>
            <Text style={styles.rowPrimary} numberOfLines={1}>{title}</Text>
            <Text style={[styles.muted, { fontSize: fs(12) }]} numberOfLines={1}>{subtitle}</Text>
          </View>
          <Ionicons name="chevron-forward" size={16} color={colors.faint} />
        </View>
      )}
    </Pressable>
  );
}

function EmptyThread({ socrates }: { socrates: boolean }) {
  return (
    <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', padding: 32, gap: 8, backgroundColor: colors.paper }}>
      <Ionicons name="chatbubbles-outline" size={36} color={colors.faint} />
      <Text style={[styles.body, { fontFamily: fonts.sansMedium }]}>Choose someone to message</Text>
      <Text style={[styles.muted, { textAlign: 'center', maxWidth: 360 }]}>
        {socrates
          ? 'Socrates is online. Members show up here while they have the app open.'
          : 'Members show up here while they have the app open. Tap someone online to start a private chat.'}
      </Text>
    </View>
  );
}

export default function Chat() {
  const { userId, loading, demo, isModerator } = useSession();
  const { online, setRoom } = usePresence();
  const { width: windowWidth } = useWindowDimensions();
  const wide = viewportWidth(windowWidth) >= SPLIT_AT;
  const [threads, setThreads] = useState<DmThread[] | null>(null);
  const [groups, setGroups] = useState<GroupChatSummary[] | null>(null);
  const [people, setPeople] = useState<Record<string, Profile>>({});
  const [blocked, setBlocked] = useState<string[]>([]);
  const [refreshing, setRefreshing] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [dmErr, setDmErr] = useState<string | null>(null);
  const [groupErr, setGroupErr] = useState<string | null>(null);
  const [q, setQ] = useState('');
  const [opening, setOpening] = useState<string | null>(null);
  const [open, setOpen] = useState<OpenThread | null>(null);
  const wasWide = useRef(wide);

  useEffect(() => { if (!loading && !userId) router.replace('/sign-in'); }, [userId, loading]);

  const load = useCallback(async () => {
    setRefreshing(true);
    try {
      const [d, g] = await Promise.all([
        listDms().then((rows) => { setDmErr(null); return rows; }).catch((e) => { setDmErr(loadErr(e)); return null; }),
        listMyGroupChats().then((rows) => { setGroupErr(null); return rows; }).catch((e) => { setGroupErr(explainEventChatError(String(e?.message ?? e), 'Couldn’t load groups.')); return null; }),
      ]);
      if (d) setThreads(d);
      setGroups(g);
      setErr(null);
    } catch (e: any) { setDmErr(loadErr(e)); } finally { setRefreshing(false); }
  }, []);
  useEffect(() => { if (userId) load(); }, [userId, load]);

  // The open thread marks itself active. Clearing here too would race that and
  // let a focused DM notify. Only the roster (no thread beside it) clears.
  const holdRoom = wide && (open?.kind === 'dm' || open?.kind === 'group');
  useFocusEffect(useCallback(() => {
    if (!holdRoom) {
      setRoom(null);
      setActivePushRoom(null);
    }
    promptWebMessageAlerts();
    if (!userId) return;
    listDms().then((d) => { setThreads(d); setDmErr(null); }).catch((e) => setDmErr(loadErr(e)));
    listMyGroupChats().then((rows) => { setGroups(rows); setGroupErr(null); }).catch((e) => setGroupErr(explainEventChatError(String(e?.message ?? e), 'Couldn’t load groups.')));
    listBlocked().then(setBlocked).catch(() => {});
  }, [userId, setRoom, holdRoom]));

  useEffect(() => {
    if (wasWide.current && !wide && open) {
      const next = open;
      setOpen(null);
      if (next.kind === 'socrates') router.push('/socrates');
      else router.push(`/rooms/${next.roomId}`);
    }
    wasWide.current = wide;
  }, [wide, open]);

  const others = useMemo(
    () => online.filter((u) => u.user_id !== userId && !blocked.includes(u.user_id)),
    [online, userId, blocked],
  );
  const profileIds = useMemo(
    () => [...new Set([...others.map((u) => u.user_id), ...(threads ?? []).map((t) => t.peer_id)])],
    [others, threads],
  );
  useEffect(() => {
    if (!profileIds.length) return;
    getProfiles(profileIds).then((p) => setPeople((cur) => ({ ...cur, ...p }))).catch(() => {});
  }, [profileIds.join('|')]);

  const needle = q.trim().toLowerCase();
  const matches = (text: string) => !needle || text.toLowerCase().includes(needle);
  const showMembers = isModerator && !demo && !!userId && matches('meetup members roster rsvps');
  // Same gate as the Ask thread. See canAskSocrates.
  const showSocrates = canAskSocrates({ userId, isModerator, demo });
  const socratesRow = includeSocrates(showSocrates, needle, SOCRATES.name, SOCRATES.subtitle);
  const labelFor = (id: string, fallback: string) => {
    const p = people[id];
    return { name: p ? primaryName(p) : fallback, handleText: p?.username ? handle(p) : null, path: p?.avatar_path };
  };

  const onlineRows = useMemo(() => others.filter((u) => {
    const p = people[u.user_id];
    return matches(`${u.name} ${p ? primaryName(p) : ''} ${p?.username ?? ''}`);
  }).sort((a, b) => (people[a.user_id] ? primaryName(people[a.user_id]) : a.name).localeCompare(people[b.user_id] ? primaryName(people[b.user_id]) : b.name)), [others, people, needle]);

  const dmRows = useMemo(() => (threads ?? []).filter((t) => {
    const p = people[t.peer_id];
    return matches(`${p ? primaryName(p) : ''} ${p?.username ?? ''} ${t.peer_id}`);
  }).sort((a, b) => {
    const ao = online.some((u) => u.user_id === a.peer_id) ? 0 : 1;
    const bo = online.some((u) => u.user_id === b.peer_id) ? 0 : 1;
    return ao - bo || b.created_at.localeCompare(a.created_at);
  }), [threads, people, online, needle]);

  const groupRows = useMemo(() => (groups ?? []).filter((chat) => matches(`${chat.title} ${chat.event_title ?? ''}`)), [groups, needle]);
  const threadPeerIds = useMemo(() => new Set((threads ?? []).map((t) => t.peer_id)), [threads]);
  // Someone you already have a thread with stays in Direct messages, with presence on that row.
  const freshOnline = useMemo(
    () => onlineRows.filter((u) => threads == null || !threadPeerIds.has(u.user_id)),
    [onlineRows, threads, threadPeerIds],
  );

  const start = async (peerId: string) => {
    if (opening) return;
    setOpening(peerId); setErr(null);
    try {
      const roomId = await openDm(peerId);
      setThreads((cur) => (cur?.some((t) => t.room_id === roomId) ? cur : [{ room_id: roomId, peer_id: peerId, created_at: new Date().toISOString() }, ...(cur ?? [])]));
      if (wide) setOpen({ kind: 'dm', roomId });
      else router.push(`/rooms/${roomId}`);
    } catch (e: any) { setErr(e.message); }
    finally { setOpening(null); }
  };

  const openSocrates = () => {
    if (wide) setOpen({ kind: 'socrates' });
    else router.push('/socrates');
  };
  const openDmRow = (roomId: string) => {
    if (wide) setOpen({ kind: 'dm', roomId });
    else router.push(`/rooms/${roomId}`);
  };
  const openGroupRow = (roomId: string) => {
    if (wide) setOpen({ kind: 'group', roomId });
    else router.push(`/rooms/${roomId}`);
  };

  const onlineCount = freshOnline.length + (socratesRow ? 1 : 0);
  const showOnlineList = socratesRow || freshOnline.length > 0;
  const showOnlineEmpty = !showOnlineList && !needle && threads != null && dmRows.length === 0;

  const roster = (
    <View testID="chat-roster" style={{ gap: 12 }}>
      <PageHeader icon="chatbubbles" title="Chat" />
      <ErrorText>{err}</ErrorText>
      <Toolbar search={q} onSearch={setQ} placeholder="Search people…" />
      {showMembers ? <ToolRow title="Meetup members" subtitle="Roster and RSVPs" label="Meetup members" onPress={() => router.push('/chat/members')} /> : null}
      {groups ? (
        <>
          <ErrorText>{groupErr}</ErrorText>
          <ListView title={groupRows.length ? `Groups · ${groupRows.length}` : 'Groups'}
            empty={<EmptyState compact icon="chatbubbles-outline" title={needle ? 'No matches' : 'No group chats yet'} body={needle ? undefined : 'When a host adds you to a chat for an event, it shows up here.'} />}>
            {groupRows.map((chat) => (
              <ConversationRow key={chat.room_id} name={chat.title} subtitle={groupChatSubtitle(chat.member_count, chat.event_count, chat.event_title)}
                label={`Open ${chat.title}`} active={open?.kind === 'group' && open.roomId === chat.room_id}
                onPress={() => openGroupRow(chat.room_id)} />
            ))}
          </ListView>
        </>
      ) : groupErr ? <ErrorText>{groupErr}</ErrorText> : null}
      {showOnlineList ? (
        <ListView title={onlineCount ? `Online now · ${onlineCount}` : 'Online now'}>
          {socratesRow ? (
            <ConversationRow key={SOCRATES_CONTACT_ID} name={SOCRATES.name} subtitle={SOCRATES.subtitle} online
              label={`Message ${SOCRATES.name}`} active={open?.kind === 'socrates'} onPress={openSocrates}
              trailing={<PresenceLabel online />} />
          ) : null}
          {freshOnline.map((u) => {
            const who = labelFor(u.user_id, u.name);
            return (
              <ConversationRow key={u.user_id} name={who.name} subtitle={opening === u.user_id ? 'Opening…' : (who.handleText ?? 'Tap to message')}
                userId={u.user_id} path={who.path} online label={`Message ${who.name}`} onPress={() => start(u.user_id)}
                trailing={<PresenceLabel online opening={opening === u.user_id} />} />
            );
          })}
        </ListView>
      ) : showOnlineEmpty ? (
        <ListView title="Online now" empty={<EmptyState icon="radio-outline" title="No other members are online right now" body="When someone has the app open, they show up here and you can message them." />} />
      ) : null}
      <ErrorText>{dmErr}</ErrorText>
      <ListView title={threads && dmRows.length ? `Direct messages · ${dmRows.length}` : 'Direct messages'} loading={!threads && !dmErr}
        empty={<EmptyState icon="chatbubble-outline" title={needle ? 'No matches' : 'No direct messages yet'} body={needle ? undefined : 'Tap someone who’s online to start a private chat.'} />}>
        {dmRows.map((t) => {
          const who = labelFor(t.peer_id, 'Member');
          const peerOnline = online.some((u) => u.user_id === t.peer_id);
          const peerBlocked = blocked.includes(t.peer_id);
          return (
            <ConversationRow key={t.room_id} name={who.name} subtitle={who.handleText ?? 'Direct message'}
              userId={t.peer_id} path={who.path} online={peerOnline && !peerBlocked}
              label={`Open chat with ${who.name}`} active={open?.kind === 'dm' && open.roomId === t.room_id}
              onPress={() => openDmRow(t.room_id)}
              trailing={<PresenceLabel online={peerOnline} blocked={peerBlocked} />} />
          );
        })}
      </ListView>
    </View>
  );

  const pane = open?.kind === 'socrates'
    ? <SocratesThread embedded />
    : open?.kind === 'dm' || open?.kind === 'group'
      ? <DirectThread key={open.roomId} roomId={open.roomId} embedded />
      : <EmptyThread socrates={showSocrates} />;

  if (wide) {
    return (
      <View style={{ flex: 1, flexDirection: 'row', minHeight: 0, backgroundColor: colors.paper }}>
        <View style={{ width: 380, minHeight: 0, borderRightWidth: 1, borderRightColor: colors.line, backgroundColor: colors.paper }}>
          <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: 14, paddingBottom: 28 }} keyboardShouldPersistTaps="handled"
            refreshControl={<RefreshControl refreshing={refreshing} onRefresh={load} />}>
            {roster}
          </ScrollView>
        </View>
        <View style={{ flex: 1, minWidth: 0, minHeight: 0 }}>{pane}</View>
      </View>
    );
  }

  return (
    <Page refreshControl={<RefreshControl refreshing={refreshing} onRefresh={load} />}>
      {roster}
    </Page>
  );
}
